/** How often the saved actions are read again, for changes made in other sessions. */
export const POLL_MS = 15_000

/** How long a shell action may run before it is killed. */
export const SHELL_TIMEOUT_MS = 120_000

/** The longest label the band draws whole; a longer one is cut with an ellipsis. */
export const LABEL_MAX_CHARS = 24

